code='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the full-width/full-height divider line.
    wall = 2
    axis = None
    idx = None
    for r, row in enumerate(grid):
        if all(v == wall for v in row):
            axis, idx = 0, r
            break
    if axis is None:
        for c in range(w):
            if all(grid[r][c] == wall for r in range(h)):
                axis, idx = 1, c
                break
    if axis is None:
        return [row[:] for row in grid]

    counts = Counter(v for row in grid for v in row if v != wall)
    bg = counts.most_common(1)[0][0]
    pts = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
           if grid[r][c] not in (wall, bg)]
    if not pts:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    # Restore the source footprint to background before moving the object.
    for r, c, _ in pts:
        out[r][c] = bg
    if axis == 0:
        dr = (idx - 1 - max(r for r, _, _ in pts)) if idx > 0 else (1 - min(r for r, _, _ in pts))
        # For a divider at the top, move the object to the row immediately below it.
        if idx == 0:
            dr = 1 - min(r for r, _, _ in pts)
        for r, c, color in pts:
            out[r + dr][c] = color
        # Paint the full line immediately beyond the moved object, away from the divider.
        trail = (max(r for r, _, _ in pts) + dr + 1) if idx < h - 1 else (min(r for r, _, _ in pts) + dr - 1)
        for c in range(w):
            out[trail][c] = 8
    else:
        dc = (idx - 1 - max(c for _, c, _ in pts)) if idx > 0 else (1 - min(c for _, c, _ in pts))
        if idx == 0:
            dc = 1 - min(c for _, c, _ in pts)
        for r, c, color in pts:
            out[r][c + dc] = color
        trail = (max(c for _, c, _ in pts) + dc + 1) if idx < w - 1 else (min(c for _, c, _ in pts) + dc - 1)
        for r in range(h):
            out[r][trail] = 8
    return out
